def depth(n):
    if n <= 1:
        return 0
    return 1 + depth(n // 2)
print(depth(16))

def qs(nums):
    if len(nums) <= 1:
        return nums
    pivot = nums[0]
    less = [x for x in nums[1:] if x < pivot]
    more = [x for x in nums[1:] if x >= pivot]
    return qs(less) + [pivot] + qs(more)
print(qs([3, 1, 2]))
